mapper.select:
SELECT *
FROM shopion.tPrdProdBrand

    AND BrandId = #{pBrandId}
    AND BrandKorName LIKE CONCAT('%',#{pBrandKorName},'%')
    AND BrandEngName LIKE CONCAT('%',#{pBrandEngName},'%')

ORDER BY ${sidx} ${sord}

mapper.update:
UPDATE shopion.tPrdProdBrand SET
    CompKorName = #{compKorName}, CompEngName = #{compEngName}, BrandKorName = #{brandKorName},
    BrandEngName = #{brandEngName}, BrandAbbrName = #{brandAbbrName},
    State = #{state}, Remark = #{remark},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE BrandId = #{brandId}
